('4.2.1a',(2+3*x)**-2,[R(1,4),-R(3,4),R(27,16),-R(27,8)]),('4.2.1b',s.sqrt(4-x),[2,-R(1,4),-R(1,64),-R(1,512)]),('4.2.1c',(8+2*x)**R(2,3),[4,R(2,3),-R(1,36),R(1,324)]),('4.2.2a',3/(5-2*x),[R(3,5),R(6,25),R(12,125),R(24,625)]),('4.2.2b',(1-x)/(2-x)**2,[R(1,4),0,-R(1,16),-R(1,16)]),('4.2.2c',s.sqrt((4+x)/(1-x)),[2,R(5,4),R(55,64),R(365,512)]),('4.2.3',(5-3*x)**-3,[R(1,125),R(9,625),R(54,3125),R(54,3125)]),('4.2.4a',1/s.sqrt(6+2*x),[s.sqrt(6)/6,-s.sqrt(6)/36,s.sqrt(6)/144]),('4.2.4b',(3*x-1)/s.sqrt(6+2*x),[-s.sqrt(6)/6,19*s.sqrt(6)/36,-13*s.sqrt(6)/144]),('4.2.5',1/s.sqrt(9+4*x),[R(1,3),-R(2,27),R(2,81),-R(20,2187)]),('4.2.6',(8-5*x)**R(1,3),[2,-R(5,12),-R(25,288)]),('4.2.7',4/(2-4*x)-2/(3-5*x),[R(4,3),R(26,9),R(166,27)]),('4.2.8',((1+x)/(8-3*x))**R(1,3),[R(1,2),R(11,48),-R(11,576)]),
